    private static String preprocess(String source,String fog){String token="#import <sodium:include/fog.glsl>";require(source.indexOf(token)>=0&&source.indexOf(token)==source.lastIndexOf(token),"Unknown import topology");int at=source.indexOf('\n')+1;String result=source.substring(0,at)+"#define TEXTURE_ARRAY\n#define USE_FOG\n#define USE_FOG_SMOOTH\n"+source.substring(at);result=result.replace(token,fog);while(result.endsWith("\n"))result=result.substring(0,result.length()-1);return result;}
    private static Map<String,String> sources(int program)throws Exception{int count=GL20.glGetProgrami(program,GL20.GL_ATTACHED_SHADERS);require(count==2,"Expected exact owned vertex/fragment pair");IntBuffer ids=BufferUtils.createIntBuffer(count);GL20.glGetAttachedShaders(program,(IntBuffer)null,ids);Map<String,String> result=new TreeMap<>();for(int i=0;i<count;i++){int id=ids.get(i),type=GL20.glGetShaderi(id,GL20.GL_SHADER_TYPE);String text=GL20.glGetShaderSource(id);require(sourceAllowed(type,text),"Unknown actual owned shader source");result.put(Integer.toString(type),hash(text.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}return result;}
    public static Map<String,Object> rowAttribute(int program,String name,int kind,int size,int location){if(!enabled()||!candidate()||!name.equals("aArcVoxelProjectionRow"))return null;require(kind==GL11.GL_UNSIGNED_INT&&size==1&&location==14,"Unknown Main row-index shader input");return Map.of("name",name,"location",location,"kind","actual-Main-physical-row-index","buffer",GL20.glGetVertexAttribi(14,GL15.GL_VERTEX_ATTRIB_ARRAY_BUFFER_BINDING),"integer",GL20.glGetVertexAttribi(14,GL30.GL_VERTEX_ATTRIB_ARRAY_INTEGER));}
    public static boolean ownedProgram(int program)throws Exception{return enabled()&&candidate()&&GL43.glGetProgramInterfacei(program,GL43.GL_SHADER_STORAGE_BLOCK,GL43.GL_ACTIVE_RESOURCES)==1&&GL43.glGetProgramResourceIndex(program,GL43.GL_SHADER_STORAGE_BLOCK,"ArcVoxelPhysicalRows")!=GL43.GL_INVALID_INDEX&&sources(program).size()==2;}
    public static void captureWorld(int pass,float partial){if(!enabled())return;if(pass>=0&&pass<3)allPassCalls[pass]++;if(!active){if(pass>=0&&pass<3)unarmedPassCalls[pass]++;return;}if(pass>=0&&pass<3)armedPassCalls[pass]++;try{require(pass==2&&Float.floatToRawIntBits(partial)==Float.floatToRawIntBits(.5f),"Unsupported actual WORLD pass/partial");require(!Minecraft.getInstance().options.anaglyph,"Stereo rendering is outside this fixed mono fixture");require(captures++==0,"Duplicated WORLD capture");events.add("pre-capture");observeNativeState("world-pre-capture");Minecraft mc=Minecraft.getInstance();int width=mc.width,height=mc.height;require(width==1280&&height==720,"Frozen FP-sword resolution differs");int draw=GL11.glGetInteger(GL30.GL_DRAW_FRAMEBUFFER_BINDING),old=GL11.glGetInteger(GL30.GL_READ_FRAMEBUFFER_BINDING),pack=GL11.glGetInteger(GL21.GL_PIXEL_PACK_BUFFER_BINDING),alignment=GL11.glGetInteger(GL11.GL_PACK_ALIGNMENT);byte[][] data=new byte[3][];try{GL30.glBindFramebuffer(GL30.GL_READ_FRAMEBUFFER,draw);GL15.glBindBuffer(GL21.GL_PIXEL_PACK_BUFFER,0);GL11.glPixelStorei(GL11.GL_PACK_ALIGNMENT,1);for(int i=0;i<3;i++){ByteBuffer bytes=BufferUtils.createByteBuffer(width*height*4);GL11.glReadPixels(0,0,width,height,i==0?GL11.GL_RGBA:GL11.GL_DEPTH_COMPONENT,i==0?GL11.GL_UNSIGNED_BYTE:i==1?GL11.GL_FLOAT:GL11.GL_UNSIGNED_INT,bytes);data[i]=new byte[bytes.capacity()];bytes.get(data[i]);}}finally{GL11.glPixelStorei(GL11.GL_PACK_ALIGNMENT,alignment);GL15.glBindBuffer(GL21.GL_PIXEL_PACK_BUFFER,pack);GL30.glBindFramebuffer(GL30.GL_READ_FRAMEBUFFER,old);}require(GL11.glGetError()==0,"WORLD raw readback GL error");frame=new LinkedHashMap<>();frame.put("width",width);frame.put("height",height);frame.put("fullUncropped",true);frame.put("origin","bottom-left");frame.put("stage","GameRenderer.render(IFJ) Profiler.hand BEFORE, WORLD pre-PolyBlur");frame.put("framebuffer",draw);frame.put("partial",partial);frame.put("actualWorldPass",pass);frame.put("anaglyph",mc.options.anaglyph);frame.put("nativeTick",mc.player.ticks);frame.put("worldTime",mc.world.getTime());frame.put("worldDayTime",mc.world.getTimeOfDay());frame.put("camera",List.of(mc.player.x,mc.player.y,mc.player.z,mc.player.yaw,mc.player.pitch,mc.options.fov));Map<String,Object> beta=new TreeMap<>();for(var e:BetaOptimizationsConfig.INSTANCE.getTree().map.entrySet())if(e.getValue()instanceof Property<?> p)beta.put(e.getKey(),p.get());frame.put("betaAll",beta);String[] names={"rgba8","depth32f","depth32u"};for(int i=0;i<3;i++){Path file=directory().resolve("physical-"+MODE+"-"+renderIndex+"."+names[i]+".gz");try(var stream=new GZIPOutputStream(Files.newOutputStream(file))){stream.write(data[i]);}frame.put(names[i],Map.of("path",file.toString(),"rawBytes",data[i].length,"sha256",hash(data[i])));}events.add("capture-complete");observeNativeState("world-capture-complete");}catch(Exception e){captureFailure=e.toString();throw new IllegalStateException("Physical ordinary WORLD capture failed",e);}}
    private static void recordAttemptBeforeAssertions(){
        Map<String,Object> value=new LinkedHashMap<>();value.put("render",renderIndex);value.put("variant",MODE);value.put("captures",captures);value.put("armedPassCalls",armedPassCalls.clone());value.put("observerFailures",new ArrayList<>(observerFailures));value.put("actualOriginalMdiReturns",actualOriginalMdiReturns);value.put("actualPreMdiDrawInspections",new ArrayList<>(drawInspections));value.put("originalVoxelObserver",lastOriginalObserver);value.put("rows",new ArrayList<>(rows));value.put("draws",new ArrayList<>(draws));value.put("actualMainLeafDecisions",new ArrayList<>(decisions));value.put("currentPhysicalCounters",counters());value.put("counterOrder",COUNTERS);value.put("beforePhysicalCounters",before.clone());value.put("physicalBootEnabled",GpuVoxelSkinPhysicalProjection.ENABLED);value.put("physicalMode",GpuVoxelSkinPhysicalProjection.MODE);value.put("fallbackReason",GpuVoxelSkinPhysicalProjection.fallbackReason);value.put("gpuVoxelBeta",BetaOptimizationsConfig.getGpuVoxelSkinLayers());value.put("gpuVoxelBackendEnabled",io.github.arcadiumclient.runtime.client.optimizations.GpuVoxelSkinPipeline.enabled);value.put("gpuVoxelStatus",io.github.arcadiumclient.runtime.client.optimizations.GpuVoxelSkinPipeline.status());value.put("forgePrepared",Boolean.getBoolean("arcadium.forge.prepared"));value.put("worldFrame",frame);value.put("nativeStates",List.copyOf(nativeStates));value.put("events",List.copyOf(events));value.put("writtenBeforeMandatoryAssertions",true);lastAttemptTelemetry=value;
        try{Files.writeString(directory().resolve("physical-attempt-"+renderIndex+".json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(value));}catch(Exception e){throw new IllegalStateException("Failure-first physical telemetry write failed",e);}
    }
    public static Map<String,Object> debugState(){Map<String,Object> out=new LinkedHashMap<>();out.put("active",active);out.put("renderIndex",renderIndex);out.put("captures",captures);out.put("allPassCalls",allPassCalls.clone());out.put("armedPassCalls",armedPassCalls.clone());out.put("unarmedPassCalls",unarmedPassCalls.clone());out.put("captureFailure",captureFailure);out.put("lastAttemptBeforeAssertions",lastAttemptTelemetry);out.put("armBoundary","before original renderWorld operation");out.put("captureBoundary","actual mono pass2 Profiler.hand BEFORE");return out;}
    public static void blur(boolean end){if(active){require(captures==1,"Blur preceded actual WORLD capture");if(!end)blurs++;events.add(end?"blur-exit":"blur-entry");observeNativeState(end?"blur-exit":"blur-entry");}}
    public static Map<String,Object> cleanup(){Map<String,Object> result=new LinkedHashMap<>();int live=0;for(Object owner:owners)try{if(field(owner,"buffers")!=null||field(owner,"commands")!=null||field(field(owner,"projection"),"buffer")!=null)live++;}catch(Exception e){throw new IllegalStateException(e);}result.put("observedOwners",owners.size());result.put("remainingOwnedStores",live);result.put("allClosed",live==0);require(live==0,"Owned physical stores survived native world close");return result;}
    private static long[] counters(){long[] values=new long[COUNTERS.length];try{for(int i=0;i<values.length;i++)values[i]=GpuVoxelSkinPhysicalProjection.class.getField(COUNTERS[i]).getLong(null);}catch(Exception e){throw new IllegalStateException(e);}return values;}
    private static Object field(Object owner,String name)throws Exception{for(Class<?> c=owner.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(owner);}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
    private static int[] read(int buffer,long offset,int count){int old=GL11.glGetInteger(GL31.GL_COPY_READ_BUFFER);try{GL42.glMemoryBarrier(GL42.GL_BUFFER_UPDATE_BARRIER_BIT|GL43.GL_SHADER_STORAGE_BARRIER_BIT);GL15.glBindBuffer(GL31.GL_COPY_READ_BUFFER,buffer);IntBuffer data=BufferUtils.createIntBuffer(count);GL15.glGetBufferSubData(GL31.GL_COPY_READ_BUFFER,offset,data);int[] words=new int[count];data.get(words);return words;}finally{GL15.glBindBuffer(GL31.GL_COPY_READ_BUFFER,old);}}
    private static int[] bits(float[] values){int[] out=new int[values.length];for(int i=0;i<out.length;i++)out[i]=Float.floatToRawIntBits(values[i]);return out;}
    private static String hash(byte[] value)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value));}
    private static Path directory(){return Path.of(System.getProperty("arcadium.playerFeatures073.output")).toAbsolutePath().getParent();}
